/**
 * Changelog modal for Aloha (ported from Hand-Math changelog view).
 * Renders window.ALOHA_CHANGELOG (generated by scripts/generateChangelog.js)
 * and wires the "Check for updates" button to the update checker.
 */
(function () {
  'use strict';

  function renderChangelog() {
    var list = document.getElementById('alohaChangelogList');
    if (!list) return;
    list.innerHTML = '';
    var entries = window.ALOHA_CHANGELOG || [];
    if (!entries.length) {
      var empty = document.createElement('p');
      empty.textContent = 'No changelog entries found.';
      list.appendChild(empty);
      return;
    }
    entries.forEach(function (c) {
      var item = document.createElement('div');
      item.className = 'aloha-changelog-item';
      var head = document.createElement('div');
      head.className = 'aloha-changelog-head';

      if (c.hash) {
        var tag = document.createElement('span');
        tag.className = 'aloha-changelog-tag';
        tag.textContent = c.hash;
        head.appendChild(tag);
      }

      if (c.date) {
        var dt = document.createElement('span');
        dt.className = 'aloha-changelog-date';
        dt.textContent = c.date + ' · ';
        head.appendChild(dt);
      }

      var subj = document.createElement('span');
      subj.className = 'aloha-changelog-subj';
      subj.textContent = c.subject || '';
      head.appendChild(subj);

      item.appendChild(head);
      if (c.body) {
        var body = document.createElement('div');
        body.className = 'aloha-changelog-body';
        body.textContent = c.body;
        item.appendChild(body);
      }
      list.appendChild(item);
    });
  }

  function toggleChangelog(open) {
    var modal = document.getElementById('alohaChangelogModal');
    if (!modal) return;
    if (open) renderChangelog();
    modal.hidden = !open;
  }

  function init() {
    var modal = document.getElementById('alohaChangelogModal');
    if (modal) {
      modal.addEventListener('click', function (e) {
        if (e.target === modal) toggleChangelog(false);
      });
    }
    document.addEventListener('keydown', function (e) {
      if (e.key === 'Escape') toggleChangelog(false);
    });

    var openBtns = document.querySelectorAll('[data-aloha-changelog-open]');
    openBtns.forEach(function (b) {
      b.addEventListener('click', function () { toggleChangelog(true); });
    });
    var closeBtns = document.querySelectorAll('[data-aloha-changelog-close]');
    closeBtns.forEach(function (b) {
      b.addEventListener('click', function () { toggleChangelog(false); });
    });
    var checkBtn = document.getElementById('alohaBtnCheckUpdates');
    if (checkBtn) {
      checkBtn.addEventListener('click', function () {
        if (window.alohaUpdateChecker) {
          window.alohaUpdateChecker.checkForUpdate(true);
        } else if (window.AlohaUpdateChecker) {
          window.alohaUpdateChecker = new window.AlohaUpdateChecker();
          window.alohaUpdateChecker.checkForUpdate(true);
        }
      });
    }
    // Auto-start the release update checker (APK + PWA); silent on failure.
    try {
      if (window.AlohaUpdateChecker && !window.alohaUpdateChecker) {
        window.alohaUpdateChecker = new window.AlohaUpdateChecker();
        window.alohaUpdateChecker.start();
      }
    } catch (e) {
      console.warn('[changelogUI] update checker start failed:', e);
    }
  }

  window.alohaChangelog = { toggle: toggleChangelog, render: renderChangelog };

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
